));
const money = (value) => new Intl.NumberFormat("en-TZ", {
  style: "currency", currency: "TZS", maximumFractionDigits: 0,
}).format(value || 0);

onMounted(async () => {
  try { plans.value = (await getPlans()).data.data || []; } catch { plans.value = []; }
});
